"""LinuxOnTab guest defaults (auto-imported by site).

Threads: since sysroot/wasm_clone.c each pthread runs on its own malloc'd
stack and musl's default is 128 KB — too small for asyncified wasm frames
running Python. Ask for 4 MB (thread stacks come from the mmap shim; 16 MB per thread exhausted the 256 MB process cap) before any thread exists.
"""
try:
    import threading
    threading.stack_size(4 * 1024 * 1024)
except Exception:
    pass
